<script>
    let audioCtx;
    let masterGain;
    let isPlaying = false;
    let timerInterval;

    // Node references
    let nodes = {
        brown: { source: null, gain: null },
        rain: { source: null, gain: null },
        fan: { source: null, gain: null }
    };

