        brown: document.getElementById('brown-slider'),
        rain: document.getElementById('rain-slider'),
        fan: document.getElementById('fan-slider')
    };
    const labels = {
        brown: document.getElementById('brown-val'),
        rain: document.getElementById('rain-val'),
        fan: document.getElementById('fan-val')
    };

