        masterGain = audioCtx.createGain();
        masterGain.gain.value = 0.001; // Start quiet for fade-in
        masterGain.connect(audioCtx.destination);

        const brownBuffer = createBrownNoiseBuffer(audioCtx);
        const pinkBuffer = createPinkNoiseBuffer(audioCtx);

        // --- Brown Noise Setup ---
        nodes.brown.source = audioCtx.createBufferSource();
        nodes.brown.source.buffer = brownBuffer;
        nodes.brown.source.loop = true;

        let brownFilter = audioCtx.createBiquadFilter();
        brownFilter.type = 'lowpass';
        brownFilter.frequency.value = 400; // Deep rumble

        nodes.brown.gain = audioCtx.createGain();
        nodes.brown.gain.gain.value = 0;

        nodes.brown.source.connect(brownFilter);
        brownFilter.connect(nodes.brown.gain);
        nodes.brown.gain.connect(masterGain);
        nodes.brown.source.start();

        // --- Rain Setup ---
        nodes.rain.source = audioCtx.createBufferSource();
        nodes.rain.source.buffer = pinkBuffer;
        nodes.rain.source.loop = true;

