        lfo.type = 'sine';
        lfo.frequency.value = 15; // 15Hz rumble

        let lfoGain = audioCtx.createGain();
        lfoGain.gain.value = 100;

        lfo.connect(lfoGain);
        lfoGain.connect(fanFilter.detune);
        lfo.start();

        nodes.fan.gain = audioCtx.createGain();
        nodes.fan.gain.gain.value = 0;

        nodes.fan.source.connect(fanFilter);
        fanFilter.connect(nodes.fan.gain);
        nodes.fan.gain.connect(masterGain);
        nodes.fan.source.start();

