            }
        }
        isPlaying = !isPlaying;
    }

    function updateVolumes() {
        if(!audioCtx) return;

        ['brown', 'rain', 'fan'].forEach(type => {
            const val = parseInt(sliders[type].value);
            labels[type].textContent = val + '%';
            // Exponential volume curve feels more natural
            const normalizedVol = (val / 100) ** 2;
            nodes[type].gain.gain.setTargetAtTime(normalizedVol, audioCtx.currentTime, 0.1);
        });
    }

    function setPreset(b, r, f) {
        sliders.brown.value = b;
        sliders.rain.value = r;
        sliders.fan.value = f;
        updateVolumes();
        if(!isPlaying) toggleAudio();
    }

    function startTimer() {
        if (!isPlaying) return;
        cancelTimer();

        const minutes = parseInt(document.getElementById('timer-select').value);
        if (minutes === 0) return;

        const display = document.getElementById('timer-display');
        let secondsRemaining = minutes * 60;

        // Fading parameters
        const fadeOutDuration = 120; // Fade out over the last 2 minutes
        const fadeStartTime = Math.max(0, secondsRemaining - fadeOutDuration);

        timerInterval = setInterval(() => {
            secondsRemaining--;

            let m = Math.floor(secondsRemaining / 60);
            let s = secondsRemaining % 60;
            display.textContent = `Fading out and stopping in ${m}m ${s.toString().padStart(2, '0')}s`;

            if (secondsRemaining === fadeOutDuration) {
                // Begin the master volume fade down
                masterGain.gain.cancelScheduledValues(audioCtx.currentTime);
                masterGain.gain.setValueAtTime(masterGain.gain.value, audioCtx.currentTime);
                masterGain.gain.linearRampToValueAtTime(0.001, audioCtx.currentTime + fadeOutDuration);
            }

            if (secondsRemaining <= 0) {
                toggleAudio();
                display.textContent = "Timer finished. Audio stopped.";
            }
        }, 1000);

        display.textContent = `Timer set for ${minutes} minutes.`;
    }

    function cancelTimer() {
        clearInterval(timerInterval);
        document.getElementById('timer-display').textContent = "";
        if (audioCtx && isPlaying) {
            masterGain.gain.cancelScheduledValues(audioCtx.currentTime);
            masterGain.gain.setTargetAtTime(1, audioCtx.currentTime, 0.5); // restore volume
        }
    }

    // Event Listeners
    btnToggle.addEventListener('click', toggleAudio);
    ['brown', 'rain', 'fan'].forEach(type => {
        sliders[type].addEventListener('input', updateVolumes);
    });

</script>
